# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: reads delulu-smash's session log (local/logs/ui/ui.jsonl, written by
#          services/ui/ui/debug_log.py) and prints a session as a timeline: what the user saw
#          in the chat, the cells they ran, the calls made for it and the errors. What an AI
#          runs first when asked to debug something that just happened in the app.
# Usage: the `ds ui debug` command (ds.cli.ui); no app imports, only the file.
#
# Example CLI Commands:
#   1. The newest session, a line per record:     ds ui debug
#   2. One chat turn with every field in full:    ds ui debug --turn 3
#   3. The sessions in the log:                   ds ui debug --list
#   4. Every session's last half hour:            ds ui debug --since 30m
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
import json
import re
from pathlib import Path
from typing import Any

from ds.util.const import REPO_DIR, UI_LOG_FILE

__all__ = ["list_sessions", "newest_session", "parse_since", "read_records", "report", "sessions"]

Record = dict[str, Any]

SUMMARY_CHARS = 100  # of a text in a one-line row; --full / --turn print all of it
SHOWN_CHARS = 60  # a one-line value this short is whole in its row: not repeated under it
# the fields printed whole under a row by --full / --turn, in this order
LONG_FIELDS = (
    "prompt",
    "added",
    "text",
    "detail",
    "code",
    "stdout",
    "args",
    "variables",
    "response",
    "reply",
    "model_requests",
    "error",
    "traceback",
    "error_body",
)
_UNITS = {"s": "seconds", "m": "minutes", "h": "hours", "d": "days"}
JOURNAL = "journalctl --user -u delulu-smash.service"


def log_files(path: Path = UI_LOG_FILE) -> list[Path]:
    """The log's files, oldest first: ui.2.jsonl, ui.1.jsonl, ui.jsonl (those that exist)."""
    older = sorted(path.parent.glob(f"{path.stem}.*{path.suffix}"), reverse=True)
    return [file for file in [*older, path] if file.exists()]


def read_records(path: Path = UI_LOG_FILE, since: dt.datetime | None = None) -> list[Record]:
    """Every kept record, oldest first, each with `at` (its time as a datetime).

    Left out: a line that isn't a record (a write cut short by a crash), and a chat row or
    cell logged again after a backend restart (`resent`) when the log already has it.
    """
    records: list[Record] = []
    seen: set[tuple[str, str]] = set()
    for file in log_files(path):
        for line in file.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                record = json.loads(line)
                record["at"] = dt.datetime.fromisoformat(record["time"])
            except (ValueError, KeyError, TypeError):
                continue
            row = (str(record.get("session", "")), str(record.get("digest", "")))
            if record.get("digest"):
                if record.get("resent") and row in seen:
                    continue
                seen.add(row)
            records.append(record)
    return [record for record in records if since is None or record["at"] >= since]


def parse_since(text: str, now: dt.datetime | None = None) -> dt.datetime:
    """'30m', '2h', '1d', '90s' ago, as a time. Raises ValueError for anything else."""
    match = re.fullmatch(r"(\d+)\s*([smhd])", text.strip().lower())
    if match is None:
        raise ValueError(f"--since takes a number and s, m, h or d (eg 30m), not {text!r}")
    now = now or dt.datetime.now().astimezone()
    return now - dt.timedelta(**{_UNITS[match[2]]: int(match[1])})


def _is_error(record: Record) -> bool:
    return (
        record.get("level") == "ERROR"
        or record.get("kind") == "error"
        or bool(record.get("error"))
        or (record.get("kind") == "chat" and record.get("source") == "error")
        or record.get("status") == "failed"
    )


def _is_turn(record: Record) -> bool:
    return record.get("kind") == "chat" and record.get("source") == "user"


def sessions(records: list[Record]) -> dict[str, list[Record]]:
    """The records of each session, in the order the sessions were last active. A record with
    no session (an app start, a browser or backend error, a call no tab made) is in none.
    """
    found: dict[str, list[Record]] = {}
    for record in records:
        if record.get("session"):
            found.setdefault(str(record["session"]), []).append(record)
    return dict(sorted(found.items(), key=lambda item: item[1][-1]["at"]))


def newest_session(records: list[Record]) -> str | None:
    """The session that was active last, None when no record has one."""
    return next(reversed(sessions(records)), None)


def _span(rows: list[Record]) -> str:
    first, last = rows[0]["at"], rows[-1]["at"]
    if first.date() == last.date():
        return f"{first:%b %d %H:%M}-{last:%H:%M}"
    return f"{first:%b %d %H:%M} - {last:%b %d %H:%M}"


def _counts(rows: list[Record]) -> str:
    turns = sum(map(_is_turn, rows))
    errors = sum(map(_is_error, rows))
    return f"{turns} turn{'s' if turns != 1 else ''} · {errors} error{'s' if errors != 1 else ''}"


def list_sessions(records: list[Record]) -> list[str]:
    """A line per session, the newest last."""
    return [f"{session}  {_span(rows)}  {_counts(rows)}" for session, rows in sessions(records).items()]


def _short(value: Any, chars: int = SUMMARY_CHARS) -> str:
    text = " ".join(str(value).split())
    return text if len(text) <= chars else f"{text[:chars]}… ({len(str(value)):,} chars)"


def _last_line(value: Any) -> str:
    lines = [line for line in str(value).strip().splitlines() if line.strip()]
    return lines[-1].strip() if lines else ""


def _parts(*parts: Any) -> str:
    return "  ".join(str(part) for part in parts if part not in ("", None))


def _ms(record: Record) -> str:
    return f"{record['ms']} ms" if record.get("ms") is not None else ""


def _chat_line(record: Record) -> str:
    kind = str(record.get("source", ""))
    text = record.get("text", "")
    if kind == "user":
        return _parts("user", record.get("key"), f'"{_short(text)}"')
    if kind == "error":
        return _parts("ERROR", _last_line(text))
    if kind == "assign":
        status = f"[{record.get('status', '')}]"
        return _parts("assign", status, record.get("name"), _short(text, 60), _error_of(record))
    return _parts(kind, record.get("name"), _short(text) if text else "")


def _error_of(record: Record) -> str:
    return f"ERROR {_last_line(record['error'])}" if record.get("error") else ""


def _call_line(record: Record) -> str:
    kind = str(record.get("kind", ""))
    name = record.get("op") or record.get("name") or ""
    if kind == "agent":
        steps = record.get("steps")
        used = f"{steps} tool call{'s' if steps != 1 else ''}" if steps is not None else ""
        cost = f"${record['cost']:.4f}" if isinstance(record.get("cost"), int | float) else ""
        return "  " + _parts("ai", record.get("source"), name, _ms(record), used, cost, _error_of(record))
    if kind == "tool":
        return "  " + _parts("tool", name, _short(record.get("args", ""), 60), _ms(record), _error_of(record))
    page = (record.get("variables") or {}).get("page") if isinstance(record.get("variables"), dict) else None
    rows = f"{record['rows']} rows" if record.get("rows") is not None else ""
    # a request with no status got no answer; a call that isn't a request has none to show
    status = record.get("status", "no answer" if record.get("url") else "")
    paged = f"page {page}" if page else ""
    return "  " + _parts(kind, record.get("source"), name, paged, status, _ms(record), rows, _error_of(record))


def line(record: Record) -> str:
    """One record as a timeline row: what the user saw flush left, the calls indented."""
    kind = record.get("kind")
    if kind == "chat":
        body = _chat_line(record)
    elif kind == "cell":
        body = _parts("cell", record.get("name"), _short(record.get("code", ""), 60), _error_of(record))
    elif kind == "app":
        body = f"-- backend {record.get('name', 'start')}ed (pid {record.get('pid', '?')}) --"
    elif kind == "error":
        body = _parts("ERROR", record.get("source"), _short(record.get("name", "")))
    else:
        body = _call_line(record)
    return f"{record['at']:%H:%M:%S} {body}"


def _full(record: Record) -> list[str]:
    """The record's long fields, whole, indented under its row."""
    lines: list[str] = []
    for name in LONG_FIELDS:
        value = record.get(name)
        if value in ("", None, [], {}):
            continue
        text = value if isinstance(value, str) else json.dumps(value, indent=2, default=str, ensure_ascii=False)
        if isinstance(value, str) and "\n" not in value and len(value) <= SHOWN_CHARS:
            continue  # all of it is in the row above
        lines.append(f"    {name}:")
        lines += [f"      {row}" for row in text.splitlines()]
    return lines


def _turn_rows(rows: list[Record], turn: int) -> list[Record]:
    """A chat turn's records: from its user row to the next turn's (the last turn-<n>, if the
    chat was cleared and the numbers started again).
    """
    starts = [i for i, record in enumerate(rows) if _is_turn(record) and record.get("key") == f"turn-{turn}"]
    if not starts:
        return []
    start = starts[-1]
    end = next((i for i in range(start + 1, len(rows)) if _is_turn(rows[i])), len(rows))
    return rows[start:end]


def report(
    records: list[Record],
    session: str = "",
    turn: int = 0,
    *,
    full: bool = False,
    every: bool = False,
    path: Path = UI_LOG_FILE,
) -> list[str]:
    """The lines `ds ui debug` prints: a header, a row per record, a closing hint.

    session: its id ('' = the newest). every: all sessions together (--since). turn: only
    that chat turn, in full. A record with no session is shown when it falls inside the
    session's time.
    """
    shown_path = path.relative_to(REPO_DIR) if path.is_relative_to(REPO_DIR) else path
    if not records:
        return [f"No log yet ({shown_path}): it starts the next time the app runs."]
    if every:
        rows, title = records, "All sessions"
    else:
        found = sessions(records)
        session = session or next(reversed(found), "")
        if session not in found:
            known = ", ".join(found) or "none"
            why = "older than the kept files, or no tab was used"
            return [f"Session {session or '?'} isn't in the log ({why}). In it: {known}"]
        first, last = found[session][0]["at"], found[session][-1]["at"]
        rows = [
            record
            for record in records
            if record.get("session") == session or (not record.get("session") and first <= record["at"] <= last)
        ]
        title = f"Session {session}"
    if turn:
        rows = _turn_rows(rows, turn)
        if not rows:
            return [f"{title} has no turn-{turn}. See its turns with: ds ui debug --session {session}"]
        title += f", turn-{turn}"
    lines = [f"{title} · {_span(rows)} · {_counts(rows)} · log: {shown_path}", ""]
    for record in rows:
        lines.append(line(record))
        if full or turn:
            lines += _full(record)
    since = f"{rows[0]['at']:%Y-%m-%d %H:%M:%S}"
    hint = "One turn in full: ds ui debug --turn <n>. " if not (full or turn) else ""
    lines += ["", f"{hint}A backend that died is only in the journal: {JOURNAL} --since '{since}'"]
    return lines
